import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) {
        List<String> keys = new ArrayList<>();
        for (int i = 1; i <= 30; i++) keys.add("key" + i);

        ConsistentHashRing ring = new ConsistentHashRing();
        ring.addServer("A");
        ring.addServer("B");
        ring.addServer("C");

        Map<String, String> before = new LinkedHashMap<>();
        for (String key : keys) before.put(key, ring.getServer(key));

        ring.addServer("D");

        int moved = 0;
        for (String key : keys) {
            String newServer = ring.getServer(key);
            if (!newServer.equals(before.get(key))) moved++;
        }
        System.out.println("Consistent hashing: after adding server D, " + moved + " out of " + keys.size() + " keys moved");

        int plainMoved = 0;
        for (String key : keys) {
            long h = djb2Hash(key);
            int oldIndex = (int) (h % 3);
            int newIndex = (int) (h % 4);
            if (oldIndex != newIndex) plainMoved++;
        }
        System.out.println("Plain modulo hashing: going from 3 to 4 servers, " + plainMoved + " out of " + keys.size() + " keys moved");
    }

    static long djb2Hash(String s) {
        long hash = 5381;
        for (int i = 0; i < s.length(); i++) {
            hash = ((hash * 33) + s.charAt(i)) % MOD;
        }
        // Plain djb2 barely spreads strings that share a prefix and differ only in
        // a trailing digit, like key1, key2, key3, so a finishing mix step (the
        // same style murmur3 uses) is needed before the hash is fit onto the ring.
        hash ^= (hash >>> 15);
        hash = (hash * 2246822519L) & 0xFFFFFFFFL;
        hash ^= (hash >>> 13);
        hash = (hash * 3266489917L) & 0xFFFFFFFFL;
        hash ^= (hash >>> 16);
        return hash;
    }

    // A simplified consistent hashing ring: servers and keys share the same hash
    // space, and each key is served by the first server found clockwise from it.
    static class ConsistentHashRing {
        private final TreeMap<Long, String> ring = new TreeMap<>();

        void addServer(String name) {
            ring.put(djb2Hash(name) % 3600, name);
        }

        String getServer(String key) {
            long position = djb2Hash(key) % 3600;
            Map.Entry<Long, String> entry = ring.ceilingEntry(position);
            if (entry == null) {
                entry = ring.firstEntry();
            }
            return entry.getValue();
        }
    }
}

