#include <iostream>
#include <string>
#include <vector>
#include <map>
using namespace std;

const long long MOD = 1000000007LL;

long long djb2Hash(const string& s) {
    long long hash = 5381;
    for (char c : s) {
        hash = ((hash * 33) + static_cast<unsigned char>(c)) % MOD;
    }
    // Plain djb2 barely spreads strings that share a prefix and differ only in
    // a trailing digit, like key1, key2, key3, so a finishing mix step (the
    // same style murmur3 uses) is needed before the hash is fit onto the ring.
    unsigned long long h = static_cast<unsigned long long>(hash);
    h ^= (h >> 15);
    h = (h * 2246822519ULL) & 0xFFFFFFFFULL;
    h ^= (h >> 13);
    h = (h * 3266489917ULL) & 0xFFFFFFFFULL;
    h ^= (h >> 16);
    return static_cast<long long>(h);
}

// A simplified consistent hashing ring: servers and keys share the same hash
// space, and each key is served by the first server found clockwise from it.
class ConsistentHashRing {
public:
    void addServer(const string& name) {
        ring[djb2Hash(name) % 3600] = name;
    }

    string getServer(const string& key) {
        long long position = djb2Hash(key) % 3600;
        auto it = ring.lower_bound(position);
        if (it == ring.end()) {
            it = ring.begin();
        }
        return it->second;
    }

private:
    map<long long, string> ring;
};

int main() {
    vector<string> keys;
    for (int i = 1; i <= 30; i++) keys.push_back("key" + to_string(i));

    ConsistentHashRing ring;
    ring.addServer("A");
    ring.addServer("B");
    ring.addServer("C");

    map<string, string> before;
    for (const auto& key : keys) before[key] = ring.getServer(key);

    ring.addServer("D");

    int moved = 0;
    for (const auto& key : keys) {
        if (ring.getServer(key) != before[key]) moved++;
    }
    cout << "Consistent hashing: after adding server D, " << moved << " out of " << keys.size() << " keys moved" << endl;

    int plainMoved = 0;
    for (const auto& key : keys) {
        long long h = djb2Hash(key);
        long long oldIndex = h % 3;
        long long newIndex = h % 4;
        if (oldIndex != newIndex) plainMoved++;
    }
    cout << "Plain modulo hashing: going from 3 to 4 servers, " << plainMoved << " out of " << keys.size() << " keys moved" << endl;

    return 0;
}
